    /** @inheritdoc */
    class WT21CourseNeedleNavIndicator extends NavIndicator {
        /** NavIndicator constructor.
         * @param navSources The possible nav sources that could be pointed to.
         * @param displayUnit The parent display unit.
         * @param bus The bus.
         */
        constructor(navSources, displayUnit, bus) {
            super(navSources, 'FMS1');
            this.displayUnit = displayUnit;
            this.bus = bus;
            this.standbyPresetSourceLabel = msfsSdk.Subject.create('');
            this.standbySources = [];
            this.standbySourceIndex = 0;
            this.setNewSource = (newSourceName) => {
                if (this.source.get().name === newSourceName) {
                    return;
                }
                if (this.standbySources[this.standbySourceIndex].name === newSourceName) {
                    this.navSwap();
                }
                else {
                    this.presetIncrease();
                    this.navSwap();
                }
            };
            this.handleSourceChange = (newSource) => {
                SimVar.SetSimVarValue('GPS DRIVES NAV1', msfsSdk.SimVarValueType.Bool, newSource.getType() === msfsSdk.NavSourceType.Gps);
                if (newSource.getType() === msfsSdk.NavSourceType.Nav) {
                    SimVar.SetSimVarValue('AUTOPILOT NAV SELECTED', msfsSdk.SimVarValueType.Number, newSource.index);
                }
                // Publishing this so AP stuff can use it on the FMC.
                this.navEventsPublisher.pub('cdi_select', {
                    index: newSource.index,
                    type: newSource.getType(),
                }, true);
            };
            this.handlePfdDcpEvent = (event) => {
                switch (event) {
                    case DcpEvent.DCP_NAV:
                        if (this.displayUnit.displayUnitConfig.displayUnitLayout === DisplayUnitLayout.Softkeys) {
                            return;
                        }
                        this.navSwap();
                        break;
                    case DcpEvent.DCP_DATA_INC:
                        this.presetIncrease();
                        break;
                    case DcpEvent.DCP_DATA_DEC:
                        this.presetDecrease();
                        break;
                }
            };
            this.navSwap = () => {
                const activeSource = this.source.get();
                const newActiveSource = this.getStandbySource();
                this.setSource(newActiveSource.name);
                this.standbySources[this.standbySourceIndex] = activeSource;
                this.updateStandbySource();
            };
            this.presetIncrease = () => {
                this.standbySourceIndex++;
                if (this.standbySourceIndex === this.standbySources.length) {
                    this.standbySourceIndex = 0;
                }
                this.updateStandbySource();
            };
            this.presetDecrease = () => {
                this.standbySourceIndex--;
                if (this.standbySourceIndex < 0) {
                    this.standbySourceIndex = this.standbySources.length - 1;
                }
                this.updateStandbySource();
            };
            this.updateStandbySourceLabel = () => {
                this.standbyPresetSourceLabel.set(this.createStandbySourceLabel());
            };
            this.navEventsPublisher = this.bus.getPublisher();
            this.standbySources = [
                this.navSources.get('NAV1'),
                this.navSources.get('NAV2'),
            ];
            this.standbyPresetSource = msfsSdk.Subject.create(this.getStandbySource());
            const dcpEvents = bus.getSubscriber();
            dcpEvents.on('dcpEvent').handle(this.handlePfdDcpEvent);
            this.updateStandbySource();
            if (this.displayUnit.displayUnitType === WT21DisplayUnitType.Pfd) {
                this.source.sub(x => this.handleSourceChange(x), true);
                this.bus.getSubscriber().on('cdi_src_set').handle((src) => {
                    if (src.type === msfsSdk.NavSourceType.Gps) {
                        this.setNewSource('FMS1');
                    }
                    else if (src.type === msfsSdk.NavSourceType.Nav) {
                        this.setNewSource(`NAV${src.index}`);
                    }
                });
            }
        }
        // eslint-disable-next-line jsdoc/require-jsdoc
        getStandbySource() {
            return this.standbySources[this.standbySourceIndex];
        }
        // eslint-disable-next-line jsdoc/require-jsdoc
        updateStandbySource() {
            this.standbyPresetSource.get().isLocalizer.unsub(this.updateStandbySourceLabel);
            this.standbyPresetSource.set(this.getStandbySource());
            this.standbyPresetSource.get().isLocalizer.sub(this.updateStandbySourceLabel);
            this.updateStandbySourceLabel();
        }
        // eslint-disable-next-line jsdoc/require-jsdoc
        createStandbySourceLabel() {
            const source = this.getStandbySource();
            if (source.getType() === msfsSdk.NavSourceType.Nav) {
                if (source.isLocalizer.get()) {
                    return 'LOC' + source.index;
                }
                else {
                    return 'VOR' + source.index;
                }
            }
            else {
                return 'FMS' + source.index;
            }
        }
    }
