    /**
     * A system to simulate fuel temperatures.
     */
    class FuelTempSystemSimple {
        /**
         * Ctor
         * @param bus The event bus.
         */
        constructor(bus) {
            this.bus = bus;
            this.ramAirTemp = msfsSdk.ConsumerSubject.create(this.bus.getSubscriber().on('ram_air_temp_c').whenChanged(), 0);
            this.leftEngineFuelFlow = msfsSdk.ConsumerSubject.create(this.bus.getSubscriber().on('fuel_flow_1').whenChanged(), 0);
            this.rightEngineFuelFlow = msfsSdk.ConsumerSubject.create(this.bus.getSubscriber().on('fuel_flow_2').whenChanged(), 0);
            this.leftTankTemp = msfsSdk.Subject.create(NaN);
            this.rightTankTemp = msfsSdk.Subject.create(NaN);
            this.previousTimestamp = 0;
            bus.getSubscriber().on('simTime').atFrequency(1 / 3).handle(this.update.bind(this));
            const publisher = bus.getPublisher();
            this.leftTankTemp.sub((v) => {
                publisher.pub('fuel_temp_1', v, false, true);
            });
            this.rightTankTemp.sub((v) => {
                publisher.pub('fuel_temp_2', v, false, true);
            });
        }
        /**
         * Updates the fuel temp values.
         * @param timestamp The current simtime timestamp.
         */
        update(timestamp) {
            this.setInitialTemperatures();
            if (this.previousTimestamp === -1) {
                this.previousTimestamp = timestamp;
            }
            let leftTankTargetTemp = this.ramAirTemp.get();
            let rightTankTargetTemp = this.ramAirTemp.get();
            if (this.leftEngineFuelFlow.get() > 10) {
                const leftLineTargetTemp = 28 + ((-40 - this.ramAirTemp.get()) * -0.1473);
                leftTankTargetTemp += (leftLineTargetTemp - leftTankTargetTemp) * 0.215;
            }
            if (this.rightEngineFuelFlow.get() > 10) {
                const rightLineTargetTemp = 28 + ((-40 - this.ramAirTemp.get()) * -0.1473);
                rightTankTargetTemp += (rightLineTargetTemp - rightTankTargetTemp) * 0.215;
            }
            const deltaTime = msfsSdk.NavMath.clamp(timestamp - this.previousTimestamp, 0, 1000);
            const tankTc = 1 / 100;
            this.adjustTemp(leftTankTargetTemp, this.leftTankTemp, tankTc, deltaTime);
            this.adjustTemp(rightTankTargetTemp, this.rightTankTemp, tankTc, deltaTime);
            this.previousTimestamp = timestamp;
        }
        /**
         * Adjusts a temperature towards a target.
         * @param target The target temperature.
         * @param temp The temperature to adjust.
         * @param timeConstant The time constant to use when adjusting the temperature.
         * @param deltaTime The current update delta time.
         */
        adjustTemp(target, temp, timeConstant, deltaTime) {
            const error = target - temp.get();
            const change = Math.sign(error) * (timeConstant / 1000) * deltaTime;
            if (Math.abs(change) >= Math.abs(error)) {
                temp.set(target);
            }
            else {
                temp.set(temp.get() + change);
            }
        }
        /**
         * Sets the initial temperatures if not already set.
         */
        setInitialTemperatures() {
            if (isNaN(this.leftTankTemp.get())) {
                this.leftTankTemp.set(this.ramAirTemp.get());
            }
            if (isNaN(this.rightTankTemp.get())) {
                this.rightTankTemp.set(this.ramAirTemp.get());
            }
        }
    }

    /**
     * An instrument for gathering engine and systems data.
     */
    class EisInstrument {
        /**
         * Create an EisInstrument
         * @param bus The event bus to publish to
         */
        constructor(bus) {
            this.engineData = msfsSdk.ObjectSubject.create({
                n1_1: 0,
                n1_2: 0,
                n2_1: 0,
                n2_2: 0,
                itt_1: 0,
                itt_2: 0,
                oil_press_1: 0,
                oil_press_2: 0,
                oil_temp_1: 0,
                oil_temp_2: 0,
                fuel_flow_1: 0,
                fuel_flow_2: 0,
                fuel_temp_1: 0,
                fuel_temp_2: 0,
                fuel_left: 0,
                fuel_right: 0,
                eng_hyd_press_1: 0,
                eng_hyd_press_2: 0,
                eng_starter_on_1: false,
                eng_starter_on_2: false,
                eng_combustion_1: false,
                eng_combustion_2: false,
                eng_ignition_switch_state_1: 0,
                eng_ignition_switch_state_2: 0,
            });
            this.surfacesData = msfsSdk.ObjectSubject.create({
                flaps_left_angle: 0,
                elevator_trim_pct: 0,
                elevator_trim_neutral_pct: 0,
                aileron_trim_pct: 0,
                rudder_trim_pct: 0,
                gear_position: 0,
            });
            this.elecData = msfsSdk.ObjectSubject.create({
                elec_bus_genalt_1_v: 0,
                elec_bus_genalt_2_v: 0,
                elec_bus_genalt_1_a: 0,
                elec_bus_genalt_2_a: 0,
                elec_bus_main_v_3: 0,
                elec_bat_a_1: 0,
            });
            this.fadecData = msfsSdk.ObjectSubject.create({
                fadec_mode_1: '',
                fadec_mode_2: '',
                fadec_tgt_n1_1: 0,
                fadec_tgt_n1_2: 0
            });
            this.fuelTempSystem = new FuelTempSystemSimple(bus);
            this.eisPub = new msfsSdk.EISPublisher(bus);
            this.surfacesPub = new msfsSdk.ControlSurfacesPublisher(bus, 3);
            this.elecPub = new msfsSdk.ElectricalPublisher(bus);
            this.fadecPub = new CJ4FadecPublisher(bus);
            this.eisSub = bus.getSubscriber();
            this.fuelTempSub = bus.getSubscriber();
            this.surfacesSub = bus.getSubscriber();
            this.elecSub = bus.getSubscriber();
            this.fadecSub = bus.getSubscriber();
            this.setupSubscriptions();
        }
        /**
         * Sets up the event subscriptions on the event bus.
         */
        setupSubscriptions() {
            for (const event in this.engineData.get()) {
                this.eisSub.on(event).withPrecision(1).handle((value) => {
                    this.engineData.set(event, value);
                });
            }
            // sub to fuel temp mock
            this.fuelTempSub.on('fuel_temp_1').withPrecision(1).handle((v) => {
                this.engineData.set('fuel_temp_1', v);
            });
            this.fuelTempSub.on('fuel_temp_2').withPrecision(1).handle((v) => {
                this.engineData.set('fuel_temp_2', v);
            });
            for (const event in this.surfacesData.get()) {
                this.surfacesSub.on(event).withPrecision(0).handle((value) => {
                    this.surfacesData.set(event, value);
                });
            }
            for (const event in this.elecData.get()) {
                this.elecSub.on(event).withPrecision(1).handle((value) => {
                    // right now we only publish the numerical values here
                    this.elecData.set(event, value);
                });
            }
            for (const event in this.fadecData.get()) {
                this.fadecSub.on(event).whenChanged().handle((value) => {
                    this.fadecData.set(event, value);
                });
            }
        }
    }

