            this.stallAoa = msfsSdk.ConsumerSubject.create(this.bus.getSubscriber().on('stall_aoa').whenChanged(), 14);
            this.flapsHandleIndex = msfsSdk.ConsumerSubject.create(this.bus.getSubscriber().on('flaps_handle_index').whenChanged(), 0);
