            this.eisInstrument.surfacesPub.onUpdate();
            this.eisInstrument.elecPub.onUpdate();
            this.eisInstrument.fadecPub.onUpdate();
            // TODO dga: maybe don't do it every frame?
            this.xmlLogicHost.update(this.instrument.deltaTime);
